tion خاصو يلغي update السابق عند rollback. not null كيحتاج إصلاح null القديمة أولا؛ default كيخص الكتابات المقبلة فهاد التسلسل. 1) setup كيعطي stock=3 وصفر طلبات. update الصحيح كينقصه لواحد؛ insert كيزيد طلبا؛ commit كيثبت الجوج. 2) بلا guard، stock=1 ما كيتبدلش ولكن insert يقدر يسجل طلبا؛ هادي هي العلة، وإرجاع if affected كيوقفها. 3) مع طلب 101 موجود، insert كيصطدم بالمفتاح؛ بعد rollback المخزون ثلاثة والطلب القديم محفوظ. 4) شغل مثال الأحداث وسجل الخطة الفعلية. الفهرس مرتب حسب الزبون والتاريخ، ولكن planner يقدر يختار خطة مختلفة حسب الإحصائيات؛ ما كاينش تسريع ثابت فالحل. 5) reserved كيبدأ null، backfill كيعمره، ثم default وnot null وcheck كيفرضو سياسة واضحة. إدخال -1 مرفوض. هاد الترتيب الصغير ماشي خطة نشر جاهزة لجدول كبير. الكود التالي هو الحالة الأساسية الكاملة؛ الاختبارات كتطبق حالات الفشل المعزولة. فالتجربة المعيبة فقط، عوض reserved_price داخل values بالعدد 4990 كذلك؛ بلا هاد التغيير not null كتوقف الإدخال لأن update ما رجع حتى ثمن، وما غاديش تعاود علة المثال القديم حرفيا. create temp table academy_products (
  id integer primary key,
  stock integer not null check (stock >= 0),
  unit_price_cents integer not null check (unit_price_cents >= 0)
);
create temp table academy_order_items (
  order_id integer primary key,
  product_id integer not null references academy_products(id),
  quantity integer not null check (quantity > 0),
  unit_price_cents integer not null check (unit_price_cents >= 0)
);
insert into academy_products values (1, 3, 4990);

begin;
do $$
declare
  affected integer;
  reserved_price integer;
begin
  update academy_products
  set stock = stock - 2
  where id = 1 and stock >= 2
  returning unit_price_cents into reserved_price;
  get diagnostics affected = row_count;
  if affected <> 1 then
    raise exception 'product missing or insufficient stock';
  end if;
  insert into academy_order_items
    (order_id, product_id, quantity, unit_price_cents)
  values (101, 1, 2, reserved_price);
end $$;
commit;
select id, stock from academy_products;
select order_id, quantity, unit_price_cents from academy_order_items;

